def critical_connections_brute(n, connections):
    def is_connected(skip_edge):
        adj = [[] for _ in range(n)]
        for u, v in connections:
            if [u, v] == skip_edge or [v, u] == skip_edge:
                continue
            adj[u].append(v)
            adj[v].append(u)
        visited = [False] * n
        stack = [0]
        visited[0] = True
        count = 1
        while stack:
            node = stack.pop()
            for nxt in adj[node]:
                if not visited[nxt]:
                    visited[nxt] = True
                    count += 1
                    stack.append(nxt)
        return count == n
    result = []
    for edge in connections:
        if not is_connected(edge):                              # FULL traversal per edge
            result.append(edge)
    return result

